-- Corrects 20260924120100: those updates matched admin-owned rows, but the live template rows have
-- owner_id NULL, so nothing was updated. This targets the four published rows by id instead.
DO $$
DECLARE _n int;
BEGIN
  UPDATE public.templates SET phases = $tpl$[{"id":"writing_development","name":"Writing & Development","mode":"Loop","summary":"Shape the manuscript, test the premise, and revise with intention.","milestones":[{"localId":"fn-capture-the-idea","name":"Capture the idea","requirement":"complete_activity_outside","note":"The moment the idea lands in your mind, write it down! Do a raw notebook dump — jotting down the backstory and ideas as they flow out of your mind, no structure yet.","provision":"diy"},{"localId":"fn-build-a-general-outline-ai-assisted-if-a","name":"Build a general outline (AI-assisted, if applicable)","requirement":"attach_a_file","note":"Map out the general outline of the story, the beginning, middle and end. AI can assist you in probing at your ideas, before world-building starts.","provision":"diy"},{"localId":"fn-world-rules-building-character-developme","name":"World & rules-building + character development","requirement":"attach_a_file","note":"Nail down the mechanics, story rules, timelines, characters and how they connect, before drafting starts.","provision":"diy"},{"localId":"fn-first-pass-skeletal-draft","name":"First-pass ‘skeletal’ draft","requirement":"attach_a_file","note":"Write out short chapters of the book to capture the premise and how the chapters will grow and connect over time — this is not a full draft yet.","provision":"diy"},{"localId":"fn-layered-iterative-revisions","name":"Layered ‘Iterative’ Revisions","requirement":"complete_activity_outside","note":"Writing a book iteratively—chapter by chapter—allows you to deeply explore the characters, extend the ideas, and deepen the plot mechanics while refining the tone and pacing as you go.","provision":"diy"},{"localId":"fn-early-spot-check-beta-read","name":"Early spot-check beta read","requirement":"request_a_service","note":"Beta readers are trusted readers that you share a couple of chapters with — lighter and earlier than the full beta round, to provide feedback that shapes the book’s development.","provision":"hire"},{"localId":"fn-deep-revisions-chapter-by-chapter-ai-ass","name":"‘Deep’ revisions, chapter by chapter (AI-assisted, if applicable)","requirement":"complete_activity_outside","note":"Deep revision requires a chapter-by-chapter focus to correct plot mistakes, balance pacing, fine-tune tone, and add clarity. Instead of hiring a professional, you can use AI as a collaborative feedback partner during this stage. AI should never write the book or substitute for your own self-editing, but it serves as a valuable second set of eyes to spot errors and inconsistencies.","provision":"diy"},{"localId":"fn-print-and-markup-pass","name":"Print-and-markup pass","requirement":"complete_activity_outside","note":"Print your book chapter by chapter, either at home or through a print shop. Editing a physical copy with a red pen catches mistakes that screen-reading misses.","provision":"diy"},{"localId":"fn-digital-manuscript-revision-of-the-marku","name":"Digital manuscript revision of the markup pass","requirement":"complete_activity_outside","note":"A distinct second step following the print-and-markup pass, is to enter your red pen edits back into the digital manuscript.","provision":"diy"},{"localId":"fn-structured-beta-reader-survey-round","name":"Structured beta-reader survey round","requirement":"request_a_service","note":"Use a real instrument to ask a set of beta-readers specific questions about your book. Give each beta reader a different segment of the book to read, so that they only have access to a limited amount. This is not just “send it and hope they do it.” Ask Pen, your book coach for a genre-based starter template.","provision":"hire"},{"localId":"fn-weigh-incorporate-beta-survey-feedback","name":"Weigh & incorporate beta-survey feedback","requirement":"complete_activity_outside","note":"Not all feedback needs you to act upon it when working with beta-readers. The real work is reflecting and deliberating on whether what your readers communicated and shared in the survey will impact or be incorporated into your work.","provision":"diy"},{"localId":"fn-full-manuscript-read-through-readiness-g","name":"Full manuscript read-through (‘readiness gate’)","requirement":"approve_a_deliverable","note":"After multiple rounds of revisions and beat readers, take time to read your book from start to finish. Your natural reaction to the book as it is, will be the gate that decides if the Writing & Development phase is actually done."},{"localId":"fn-draft-front-back-matter-content","name":"Draft front/back matter content","requirement":"attach_a_file","note":"Chapter books and novels often include a variety of front and back matter, such as acknowledgments, about the author, table of contents, dedication, prologue or epilogue. Spend time writing the content — don’t worry about formatting it, that happens later in the Production phase. Note: Page number accuracy is not important at this time. This will be finalized in the Production phase.","provision":"diy"},{"localId":"fn-draft-back-cover-summary-blurb-copy","name":"Draft back-cover summary / blurb copy","requirement":"attach_a_file","note":"Important elements of your book and when posting the book’s description online is to capture the back-cover summary or short blurb copy. These appear in your book listing on various digital platforms.","provision":"diy"},{"localId":"fn-set-a-tentative-placeholder-publication-","name":"Set a tentative / placeholder publication date","requirement":"complete_activity_outside","note":"Early on in the book writing process, take time to set a lightweight, flexible date to serve as a placeholder that reflects when you would hope to publish your book. This would be the ideal date that you would click ‘publish’ online or that pre-sales would go live. This date is used in the Author’s Workshop to inform your phasing schedule. This date will be ‘firmed up’ later in the Pre-Launch phase."},{"localId":"fn-create-an-author-website-conditional","name":"Create an author website (conditional)","requirement":"complete_activity_outside","note":"[Skip this one if you already have an author website.] Authors need a place of their own online to share their work. An author website can include, but not limited to: your published book listings, author events, blog posts, newsletter sign up forms, and marketing materials.","provision":"diy"},{"localId":"fn-start-lightweight-list-building","name":"Start lightweight list-building","requirement":"complete_activity_outside","note":"You need to begin building an audience early on in the book writing process. Grow your following or email list by creating a sign-up landing page or casual “here's what I'm working on” blog posts. This audience building starts here, but it is more present in the Pre-Launch phase.","provision":"diy"}]},{"id":"editing","name":"Editing","mode":"Loop","summary":"Move from structural clarity to clean, confident prose.","milestones":[{"localId":"fn-copyedit-pass-chapter-by-chapter-ai-assi","name":"Copyedit pass, chapter by chapter (AI-assisted, if applicable)","requirement":"complete_activity_outside","note":"At this point in the editing phase your goal is to make final adjustments to grammar, punctuation, and ensure there is consistency across the chapters and plot. Use the same chapter-by-chapter pattern as Deep Revision. During this time, AI can serve as a second pair of eyes, or as a thinking partner who can spot inconsistencies for you. AI should never replace the author of the work — and is never a substitute for a professional pass when budget allows.","provision":"diy"},{"localId":"fn-full-read-through-gate","name":"Full read-through gate","requirement":"approve_a_deliverable","note":"By this point your read-through should begin to provide confirmation that the manuscript is genuinely done. When your manuscript gets to this point, it will mark the end of the Writing & Development phase."},{"localId":"fn-lock-manuscript","name":"Lock manuscript","requirement":"complete_activity_outside","note":"When you deem the manuscript as ready for production, this is the moment you freeze the copy. The only changes that will occur from this point forward are ‘formatting changes’ related to the book’s selected trim, fonts, or other non-text edits.","provision":"diy"}]},{"id":"production","name":"Production","mode":"Sprint","summary":"Turn the manuscript into a book people can hold and read.","milestones":[{"localId":"fn-select-cover-format-type","name":"Select cover format type","requirement":"complete_activity_outside","note":"Selecting to publish your book as a hardcover and/or as a paperback can impact the trim options allowed for publishing. Select the option that you desire to determine which trim size would work best for your book and if there is a minimum or maximum page count needed for the selected trim size."},{"localId":"fn-interior-formatting","name":"Interior formatting","requirement":"attach_a_file","note":"Whether you format the book yourself or hire someone, this is where the final interior file gets completed, and built to the trim size chosen earlier. Check your selected publication site for a downloadable template that you can use. During this time, it is recommended that authors make a copy of the original manuscript to make trim format-modifications.","track":"text"},{"localId":"fn-add-page-numbers-headers-and-footers","name":"Add page numbers, headers, and footers","requirement":"attach_a_file","note":"A tricky, time-consuming part of preparing the interiors of your book is ensuring the page headers and footers are properly configured. When using a downloaded template, they are typically configured accordingly, so each time a new page is added in a section, the document corrects itself. Add page numbers to the bottom of your book pages. Make sure your front and back matter is all in place, headers show on the correct pages, and the footer is configured with the page number placement you want. Page numbers will be fully locked in later in this phase.","track":"text","provision":"diy"},{"localId":"fn-update-table-of-contents","name":"Update table of contents","requirement":"attach_a_file","note":"Inserting page numbers and configuring them accurately across front matter, interior text, and back matter can be a time-consuming process. Sections in the book template impact how the numbering appears. Once pages are numbered as best as they can be, update the table of contents. It is important to not stress too much right now about the numbering. A few milestones down, when the book is previewed in the publication’s site, that will be the time to determine page-placement changes.","track":"text","provision":"diy"},{"localId":"fn-cover-design-interior-image-design","name":"Cover design / interior image design","requirement":"request_a_service","note":"Cover design and any interior image designs run in parallel with the interior formatting milestone. With chapter books, AI can be used as a helpful tool to generate images that can be used as interior images or for generating the front cover, back cover, and spine. Be aware that this part of the process will take time and include multiple iterations. Getting the book cover correctly sized and formatted to be approved by your publication site, is a learning process that requires patience.","track":"design"},{"localId":"fn-book-draft-creation-on-amazon-kdp-and-or","name":"Book draft creation on Amazon KDP and/or Ingramspark","requirement":"complete_activity_outside","note":"Create an account or login to your chosen publication sites (e.g., Amazon KDP or Ingramspark). Enter all the necessary details about your book and its content. [This milestone runs parallel to the following two regarding the ISBN decisions.]","track":"publishing","provision":"diy"},{"localId":"fn-isbn-decision-free-vs-purchased","name":"ISBN decision: free vs. purchased","requirement":"complete_activity_outside","note":"A real decision with real consequences — switching later means redoing every file the ISBN touches. When you begin drafting your book’s listing in your publication site(s), it will ask for you to enter your book’s ISBN number. This is where you need to determine if you have to budget to purchase your own ISBN number or opt for a free ISBN number that you can get on your publication’s site. Ask Pen to walk through the tradeoffs before deciding.","track":"publishing"},{"localId":"fn-isbn-purchase-quantity","name":"ISBN purchase & quantity","requirement":"complete_activity_outside","note":"You can buy ISBN numbers through Bowker (US) or your country's ISBN agency. You will need to purchase a different ISBN number for each print format you publish your book as (e.g., paperback, hardback, ebook) — the KDP ebook needs none. Upon purchase, input the purchased or free ISBN in your book listing’s draft. Note: If you plan to list your book as pre-order, you have to use the same purchased ISBN number across Ingramspark and Amazon KDP for them to link up accurately.","track":"publishing","provision":"diy"},{"localId":"fn-cover-and-manuscript-upload-approval","name":"Cover and manuscript upload approval","requirement":"complete_activity_outside","note":"Whether you are self-publishing directly on Amazon KDP or Ingramspark — you have to upload the manuscript and cover (likely multiple times) before it is approved without errors. Your book can remain in draft mode for as long as necessary until you get this part right. Once both are uploaded, the sites will trigger their automated format-check on your manuscript and cover files.","track":"publishing","provision":"diy"},{"localId":"fn-ingramspark-and-amazon-kdp-listing-forma","name":"IngramSpark and Amazon KDP listing + format final check","requirement":"complete_activity_outside","note":"Once your book details are added and your manuscript and cover are approved with no errors, you are ready to ‘submit your book for publication’. This can be done directly on IngramSpark using a future publication date, while in parallel with the KDP draft, which runs its own format check too.","track":"publishing","provision":"diy"},{"localId":"fn-ingramspark-preorder-scheduling","name":"IngramSpark preorder scheduling","requirement":"complete_activity_outside","note":"Are you planning to release your book with a ‘pre-order date’? This means that readers can begin ordering your book with scheduled deliveries before it is an active publication. This option is only offered on IngramSpark. In order for a ‘pre-order’ listing to appear on Amazon KDP, your Ingramspark listing and KDP listing need to use the same ISBN number. Connecting it to the KDP draft has a real lead time — don't leave this until the last minute. It makes several days or weeks before Ingramspark and KDP communicate together and for it to appear as a pre-order on Amazon.","track":"publishing","provision":"diy"},{"localId":"fn-build-the-ebook-file","name":"Build the ebook file","requirement":"attach_a_file","note":"If you are planning to offer an ebook through Kindle or Ingramspark, take time to create it directly in KDP's own ebook tool — no separate ISBN required for this format.","track":"text","provision":"diy"},{"localId":"fn-set-final-pricing-across-formats","name":"Set final pricing across formats","requirement":"complete_activity_outside","note":"Think through how you want to price your book out. When listing it on publishing sites, there are costs associated with Royalties that vary. Set prices directly on each platform — KDP, IngramSpark, and any others you're using.","track":"publishing","provision":"diy"},{"localId":"fn-order-physically-verify-proof-copies","name":"Order & physically verify proof copies","requirement":"complete_activity_outside","note":"Once your book’s cover and manuscript have been approved, it is highly recommended that you order a real, physical proof from both KDP and IngramSpark and check it by hand — the human check that catches what automated format-checks can't. Note: these review proofs are typically stamped “not for resale” by the platform — your separate, sellable author copies are ordered later, in Post-Launch.","track":"publishing","provision":"diy"}]},{"id":"pre_launch","name":"Pre-Launch","mode":"Sprint","summary":"Prepare the listing, early readers, and a realistic launch plan.","milestones":[{"localId":"fn-firm-up-the-pub-date","name":"Firm up the pub date","requirement":"complete_activity_outside","note":"Previously you set a tentative publication date, now it is time to commit to the actual publish date. This flips the placeholder date from Writing & Development to a confirmed date.","provision":"diy"},{"localId":"fn-build-activate-the-arc-team-advance-read","name":"Build & activate the ARC team - (Advance Reader Copy team)","requirement":"request_a_service","note":"An Advance Reader Copy team is a group of dedicated readers who receive a free, pre-publication copy of your book in exchange for posting an honest review on launch day or shortly after that you need the longest lead time in this phase. If you have never ran one before, you can ask Pen — She’ll walk you through what an ARC team actually is and how to recruit one.","provision":"hire"},{"localId":"fn-continue-list-building-at-higher-intensi","name":"Continue list-building at higher intensity","requirement":"complete_activity_outside","note":"This milestone is dedicated to reminding you that it is important to continue to build the reader list you started back in the Writing & Development phase, but now you are building it with more urgency.","provision":"diy"},{"localId":"fn-content-marketing-on-social-media-bloggi","name":"Content marketing on social media / blogging begins","requirement":"complete_activity_outside","note":"This is where you begin writing blogs and marketing content with a concrete purpose. Creating content and collateral with real images — a cover reveal, a title reveal, an excerpt — builds reader interest and motivation to order your book. This is why building your list has been important up to this point.","provision":"diy"},{"localId":"fn-ebook-preorder-goes-live","name":"Ebook preorder goes live","requirement":"complete_activity_outside","note":"Live on the platform you're using for preorders — gives your marketing somewhere to actually send people. Ebooks are allowed on Amazon KDP to have a ‘Scheduled Date’, which allows you to funnel readers to an actual listing page.","provision":"diy"},{"localId":"fn-secure-early-editorial-reviews","name":"Secure early editorial reviews","requirement":"request_a_service","note":"Early editorial reviews are different from your ARC readers' own reviews. Editorial reviews typically come from editorial outlets or professional reviewers, such as written by professional reviewers, journalists, specialized bloggers, or other authors in the same genre.","provision":"hire"},{"localId":"fn-final-sprint","name":"Final sprint","requirement":"complete_activity_outside","note":"Down to the last 1–2 weeks — the official countdown has begun for emails, reminder posts, to give the final push before launch.","provision":"diy"}]},{"id":"launch","name":"Launch","mode":"Launch window","summary":"Publish, verify every storefront, and invite the first readers.","milestones":[{"localId":"fn-click-publish","name":"Click ‘Publish’","requirement":"complete_activity_outside","note":"This milestone is for the day your book is set to go live and be published. The day that readers can order their official copy. This is the single action that everything before has been building toward.","provision":"diy"},{"localId":"fn-verify-live-and-correct-on-both-platform","name":"Verify live and correct on both platforms","requirement":"approve_a_deliverable","note":"As soon as you click, ‘Publish’ you are going to want to shout it to the world, but take a moment to confirm that on each publication site your listing and links are working properly. This will help prevent errors before you announce."},{"localId":"fn-announce-blog-post","name":"Announce: blog post","requirement":"complete_activity_outside","note":"Publish a launch-day post on your own site.","provision":"diy"},{"localId":"fn-announce-social-media","name":"Announce: social media","requirement":"complete_activity_outside","note":"Share the launch across your social media channels.","provision":"diy"},{"localId":"fn-announce-email-list","name":"Announce: email list","requirement":"complete_activity_outside","note":"Email your list of readers that you have been building up to this point to let them know that the book is live.","provision":"diy"},{"localId":"fn-update-author-website-preorder-live","name":"Update author website (preorder → live)","requirement":"complete_activity_outside","note":"A small, easy-to-forget step is to flip your site's book status on the same day you publish, not days later. If you have banners on your site or a heading listing your book as ‘Pre-Order’ update this to ‘Now Available.’","provision":"diy"}]},{"id":"post_launch_growth","name":"Post-Launch & Growth","mode":"Loop","summary":"Learn from the launch and build steady readership.","milestones":[{"localId":"fn-marketing-push-begins-with-changed-messa","name":"Marketing push begins, with changed messaging","requirement":"complete_activity_outside","note":"Using the same channels as before to share different messaging. Begin to shift messaging from anticipation copy to reader-response energy.","provision":"diy"},{"localId":"fn-order-author-copies","name":"Order author copies","requirement":"complete_activity_outside","note":"Don’t forget to order your own stock of physical books for book signings, gifts, and direct sales. This is the final product that will no longer contain the ‘Proof Copy’ label from the Production phase.","provision":"diy"}]}]$tpl$::jsonb, updated_at = now() WHERE id = '4dea60f2-bd45-4a5e-a5ef-f2675e2a199e' AND owner_id IS NULL;
  GET DIAGNOSTICS _n = ROW_COUNT; RAISE NOTICE 'Fiction Novel: % template row(s) updated', _n;
  UPDATE public.templates SET phases = $tpl$[{"id":"writing_development","name":"Writing & Development","mode":"Loop","summary":"Shape the manuscript, test the premise, and revise with intention.","milestones":[{"localId":"mm-capture-the-idea-core-memory-or-throughl","name":"Capture the idea / core memory or throughline","requirement":"complete_activity_outside","note":"Raw notebook dump — the memory, emotional core, and reason this story needs telling, no structure yet.","provision":"diy"},{"localId":"mm-build-a-general-outline-ai-assisted","name":"Build a general outline (AI-assisted)","requirement":"attach_a_file","note":"AI-assisted, before drafting starts.","provision":"diy"},{"localId":"mm-identify-real-people-who-ll-appear-and-n","name":"Identify real people who'll appear and note permission/privacy considerations early","requirement":"complete_activity_outside","note":"Flag everyone depicted now, before drafting goes further — this shapes what you can safely write and may need real releases later.","provision":"diy"},{"localId":"mm-skeletal-first-pass-draft","name":"Skeletal first-pass draft","requirement":"attach_a_file","note":"Short chapters capturing how the story connects — not a full draft yet.","provision":"diy"},{"localId":"mm-layered-revision-passes","name":"Layered revision passes","requirement":"complete_activity_outside","note":"Extending and deepening each chapter over multiple rounds.","provision":"diy"},{"localId":"mm-early-spot-check-beta-read","name":"Early spot-check beta read","requirement":"request_a_service","note":"1–2 trusted readers, a couple of chapters only — lighter and earlier than the full beta round.","provision":"hire"},{"localId":"mm-deep-revision-chapter-by-chapter-ai-assi","name":"Deep revision, chapter by chapter (AI-assisted)","requirement":"complete_activity_outside","note":"AI is a feedback and thinking partner here, never the author of the work — and never a substitute for a professional pass when budget allows.","provision":"diy"},{"localId":"mm-print-and-markup-pass","name":"Print-and-markup pass","requirement":"complete_activity_outside","note":"Read a physical printout with a red pen — catches what screen-reading misses.","provision":"diy"},{"localId":"mm-digital-transcription","name":"Digital transcription","requirement":"complete_activity_outside","note":"A distinct second step — not the same session as the print-and-markup pass.","provision":"diy"},{"localId":"mm-structured-beta-reader-survey-round","name":"Structured beta-reader survey round","requirement":"request_a_service","note":"A real instrument with specific questions, not just “send it and hope.” Ask Pen for a genre-based starter template.","provision":"hire"},{"localId":"mm-weigh-incorporate-feedback","name":"Weigh & incorporate feedback","requirement":"complete_activity_outside","note":"The deliberate judgment call after the survey, distinct from collecting it.","provision":"diy"},{"localId":"mm-full-manuscript-read-through-readiness-g","name":"Full manuscript read-through (readiness gate)","requirement":"approve_a_deliverable","note":"The gate that decides Writing & Development is actually done."},{"localId":"mm-draft-front-back-matter-content","name":"Draft front/back matter content","requirement":"attach_a_file","note":"Acknowledgments, about the author, table of contents, dedication.","provision":"diy"},{"localId":"mm-draft-back-cover-summary-blurb-copy","name":"Draft back-cover summary / blurb copy","requirement":"attach_a_file","note":"The back-cover summary or blurb copy.","provision":"diy"},{"localId":"mm-set-a-tentative-placeholder-target-pub-d","name":"Set a tentative/placeholder target pub date","requirement":"complete_activity_outside","note":"Lightweight and early — feeds the schedule without a firm commitment."},{"localId":"mm-start-lightweight-list-building","name":"Start lightweight list-building","requirement":"complete_activity_outside","note":"A sign-up page plus casual behind-the-scenes posts. Starts here, not in Pre-Launch.","provision":"diy"},{"localId":"mm-create-an-author-website-conditional","name":"Create an author website (conditional)","requirement":"complete_activity_outside","note":"Skip this one if you already have a site.","provision":"diy"}]},{"id":"editing","name":"Editing","mode":"Loop","summary":"Move from structural clarity to clean, confident prose.","milestones":[{"localId":"mm-copyedit-pass-ai-assisted-chapter-by-cha","name":"Copyedit pass, AI-assisted, chapter by chapter","requirement":"complete_activity_outside","note":"AI is a feedback and thinking partner here, never the author of the work — and never a substitute for a professional pass when budget allows.","provision":"diy"},{"localId":"mm-legal-sensitivity-read","name":"Legal/sensitivity read","requirement":"request_a_service","note":"Privacy and defamation risk are specific to writing about real people — worth the cost of a professional pass if the budget allows.","provision":"hire"},{"localId":"mm-full-read-through-gate","name":"Full read-through gate","requirement":"approve_a_deliverable","note":"The gate that confirms Editing is actually done."},{"localId":"mm-lock-manuscript","name":"Lock manuscript","requirement":"complete_activity_outside","note":"Freeze the text here — only formatting changes from this point forward.","provision":"diy"}]},{"id":"production","name":"Production","mode":"Sprint","summary":"Turn the manuscript into a book people can hold and read.","milestones":[{"localId":"mm-select-cover-format-type","name":"Select cover format type","requirement":"complete_activity_outside","note":"Selecting to publish your book as a hardcover and/or as a paperback can impact the trim options allowed for publishing. Select the option that you desire to determine which trim size would work best for your book and if there is a minimum or maximum page count needed for the selected trim size."},{"localId":"mm-interior-formatting","name":"Interior formatting","requirement":"attach_a_file","note":"Whether you format it yourself or hire someone, this is where the final interior file gets attached, built to the trim size chosen earlier.","track":"text"},{"localId":"mm-add-page-numbers-headers-and-footers","name":"Add page numbers, headers, and footers","requirement":"attach_a_file","note":"A tricky, time-consuming part of preparing the interiors of your book is ensuring the page headers and footers are properly configured. When using a downloaded template, they are typically configured accordingly, so each time a new page is added in a section, the document corrects itself. Add page numbers to the bottom of your book pages. Make sure your front and back matter is all in place, headers show on the correct pages, and the footer is configured with the page number placement you want. Page numbers will be fully locked in later in this phase.","track":"text","provision":"diy"},{"localId":"mm-update-table-of-contents","name":"Update table of contents","requirement":"attach_a_file","note":"Inserting page numbers and configuring them accurately across front matter, interior text, and back matter can be a time-consuming process. Sections in the book template impact how the numbering appears. Once pages are numbered as best as they can be, update the table of contents. It is important to not stress too much right now about the numbering. A few milestones down, when the book is previewed in the publication’s site, that will be the time to determine page-placement changes.","track":"text","provision":"diy"},{"localId":"mm-cover-design","name":"Cover design","requirement":"request_a_service","note":"Runs in parallel with interior formatting. Ask Pen to weigh DIY cover tools against hiring a designer based on your budget.","track":"design"},{"localId":"mm-book-draft-creation-on-amazon-kdp-and-or","name":"Book draft creation on Amazon KDP and/or Ingramspark","requirement":"complete_activity_outside","note":"Create an account or login to your chosen publication sites (e.g., Amazon KDP or Ingramspark). Enter all the necessary details about your book and its content. [This milestone runs parallel to the following two regarding the ISBN decisions.]","track":"publishing","provision":"diy"},{"localId":"mm-isbn-decision-free-vs-purchased","name":"ISBN decision: free vs. purchased","requirement":"complete_activity_outside","note":"A real decision with real consequences — switching later means redoing every file the ISBN touches. Ask Pen to walk through the tradeoffs.","track":"publishing"},{"localId":"mm-isbn-purchase-quantity","name":"ISBN purchase & quantity","requirement":"complete_activity_outside","note":"Buy through Bowker (US) or your country's ISBN agency — one per print format; the KDP ebook needs none.","track":"publishing","provision":"diy"},{"localId":"mm-cover-and-manuscript-upload-approval","name":"Cover and manuscript upload approval","requirement":"complete_activity_outside","note":"Whether you are self-publishing directly on Amazon KDP or Ingramspark — you have to upload the manuscript and cover (likely multiple times) before it is approved without errors. Your book can remain in draft mode for as long as necessary until you get this part right. Once both are uploaded, the sites will trigger their automated format-check on your manuscript and cover files.","track":"publishing","provision":"diy"},{"localId":"mm-ingramspark-and-amazon-kdp-listing-forma","name":"IngramSpark and Amazon KDP listing + format final check","requirement":"complete_activity_outside","note":"Once your book details are added and your manuscript and cover are approved with no errors, you are ready to ‘submit your book for publication’. This can be done directly on IngramSpark using a future publication date, while in parallel with the KDP draft, which runs its own format check too.","track":"publishing","provision":"diy"},{"localId":"mm-ingramspark-preorder-scheduling","name":"IngramSpark preorder scheduling","requirement":"complete_activity_outside","note":"Scheduled on IngramSpark. Connecting it to the KDP draft has a real lead time.","track":"publishing","provision":"diy"},{"localId":"mm-build-the-ebook-file","name":"Build the ebook file","requirement":"attach_a_file","note":"Built directly in KDP's own ebook tool — no separate ISBN required for this format.","track":"text","provision":"diy"},{"localId":"mm-set-final-pricing","name":"Set final pricing","requirement":"complete_activity_outside","note":"Set directly on each platform — KDP, IngramSpark, and any others you're using.","track":"publishing","provision":"diy"},{"localId":"mm-order-physically-verify-proof-copies","name":"Order & physically verify proof copies","requirement":"complete_activity_outside","note":"Order a real, physical proof from both platforms and check it by hand — the human check that catches what automated format-checks can't.","track":"publishing","provision":"diy"}]},{"id":"pre_launch","name":"Pre-Launch","mode":"Sprint","summary":"Prepare the listing, early readers, and a realistic launch plan.","milestones":[{"localId":"mm-firm-up-the-pub-date","name":"Firm up the pub date","requirement":"complete_activity_outside","note":"The second, harder date commitment — flips the placeholder date to confirmed.","provision":"diy"},{"localId":"mm-build-activate-the-arc-team","name":"Build & activate the ARC team","requirement":"request_a_service","note":"Needs the longest lead time in this phase. Never run one before? Ask Pen — it'll walk you through what an ARC team is and how to recruit one.","provision":"hire"},{"localId":"mm-continue-list-building","name":"Continue list-building","requirement":"complete_activity_outside","note":"A continuation of the list you started earlier, now with more urgency.","provision":"diy"},{"localId":"mm-content-marketing-blogging-begins","name":"Content marketing / blogging begins","requirement":"complete_activity_outside","note":"Needs something concrete to be about — a cover reveal, a title reveal, an excerpt.","provision":"diy"},{"localId":"mm-ebook-preorder-goes-live","name":"Ebook preorder goes live","requirement":"complete_activity_outside","note":"Live on the platform you're using for preorders.","provision":"diy"},{"localId":"mm-secure-early-editorial-reviews","name":"Secure early/editorial reviews","requirement":"request_a_service","note":"Distinct from your ARC readers' own reviews — typically from editorial outlets or professional reviewers.","provision":"hire"},{"localId":"mm-final-sprint","name":"Final sprint","requirement":"complete_activity_outside","note":"The last 1–2 weeks — countdown emails, reminder posts, the final push.","provision":"diy"}]},{"id":"launch","name":"Launch","mode":"Launch window","summary":"Publish, verify every storefront, and invite the first readers.","milestones":[{"localId":"mm-click-publish","name":"Click publish","requirement":"complete_activity_outside","note":"The single action everything before it has been building toward.","provision":"diy"},{"localId":"mm-verify-live-and-correct-on-both-platform","name":"Verify live and correct on both platforms","requirement":"approve_a_deliverable","note":"Confirm before you announce — this instinct has run through every gate in this template."},{"localId":"mm-announce-social-media","name":"Announce: social media","requirement":"complete_activity_outside","note":"Share the launch across your social channels.","provision":"diy"},{"localId":"mm-announce-blog-post","name":"Announce: blog post","requirement":"complete_activity_outside","note":"Publish a launch-day post on your own site.","provision":"diy"},{"localId":"mm-announce-email-list","name":"Announce: email list","requirement":"complete_activity_outside","note":"Email your list that the book is live.","provision":"diy"},{"localId":"mm-update-author-website-preorder-live","name":"Update author website (preorder → live)","requirement":"complete_activity_outside","note":"A small, easy-to-forget step — flip your site's status the same day you publish.","provision":"diy"}]},{"id":"post_launch_growth","name":"Post-Launch & Growth","mode":"Loop","summary":"Learn from the launch and build steady readership.","milestones":[{"localId":"mm-marketing-push-begins-with-changed-messa","name":"Marketing push begins, with changed messaging","requirement":"complete_activity_outside","note":"Same channels as before, different message — shift from anticipation copy to reader-response energy.","provision":"diy"},{"localId":"mm-order-author-copies","name":"Order author copies","requirement":"complete_activity_outside","note":"Physical stock for signings, gifts, and direct sales.","provision":"diy"}]}]$tpl$::jsonb, updated_at = now() WHERE id = 'a9832380-7d91-425b-86b0-97ae217ceb4d' AND owner_id IS NULL;
  GET DIAGNOSTICS _n = ROW_COUNT; RAISE NOTICE 'Memoir: % template row(s) updated', _n;
  UPDATE public.templates SET phases = $tpl$[{"id":"writing_development","name":"Writing & Development","mode":"Loop","summary":"Shape the manuscript, test the premise, and revise with intention.","milestones":[{"localId":"nf-capture-the-idea-core-premise","name":"Capture the idea / core premise","requirement":"complete_activity_outside","note":"Raw notebook dump — the core premise and promise to the reader, no structure yet.","provision":"diy"},{"localId":"nf-research-and-gather-comparable-titles","name":"Research and gather comparable titles","requirement":"complete_activity_outside","note":"Understand what's already published in this space and where your book fits — shapes positioning, cover direction, and format decisions later.","provision":"diy"},{"localId":"nf-build-a-detailed-outline-working-table-o","name":"Build a detailed outline / working table of contents (AI-assisted)","requirement":"attach_a_file","note":"For nonfiction, the outline often is the book's real structure, not just a guide — worth more time here than a novel's outline gets.","provision":"diy"},{"localId":"nf-skeletal-first-pass-draft-chapter-by-cha","name":"Skeletal first-pass draft, chapter by chapter","requirement":"attach_a_file","note":"Short chapters capturing the argument and how they connect — not a full draft yet.","provision":"diy"},{"localId":"nf-layered-revision-passes","name":"Layered revision passes","requirement":"complete_activity_outside","note":"Extending and deepening each chapter over multiple rounds.","provision":"diy"},{"localId":"nf-early-spot-check-beta-expert-read","name":"Early spot-check beta/expert read","requirement":"request_a_service","note":"1–2 trusted readers or a subject expert, a couple of chapters only — lighter and earlier than the full beta round.","provision":"hire"},{"localId":"nf-deep-revision-chapter-by-chapter-ai-assi","name":"Deep revision, chapter by chapter (AI-assisted)","requirement":"complete_activity_outside","note":"AI is a feedback and thinking partner here, never the author of the work — and never a substitute for a professional pass when budget allows.","provision":"diy"},{"localId":"nf-print-and-markup-pass","name":"Print-and-markup pass","requirement":"complete_activity_outside","note":"Read a physical printout with a red pen — catches what screen-reading misses.","provision":"diy"},{"localId":"nf-digital-transcription","name":"Digital transcription","requirement":"complete_activity_outside","note":"A distinct second step — not the same session as the print-and-markup pass.","provision":"diy"},{"localId":"nf-structured-beta-reader-survey-round","name":"Structured beta-reader survey round","requirement":"request_a_service","note":"A real instrument with specific questions. Consider a subject-matter-expert review here too, not just peer readers.","provision":"hire"},{"localId":"nf-weigh-incorporate-feedback","name":"Weigh & incorporate feedback","requirement":"complete_activity_outside","note":"The deliberate judgment call after the survey, distinct from collecting it.","provision":"diy"},{"localId":"nf-full-manuscript-read-through-readiness-g","name":"Full manuscript read-through (readiness gate)","requirement":"approve_a_deliverable","note":"The gate that decides Writing & Development is actually done."},{"localId":"nf-draft-front-back-matter-content-includin","name":"Draft front/back matter content (including index plan)","requirement":"attach_a_file","note":"Acknowledgments, about the author — plus planning what the index will need to cover; the index itself gets built in Production.","provision":"diy"},{"localId":"nf-draft-back-cover-summary-blurb-copy","name":"Draft back-cover summary / blurb copy","requirement":"attach_a_file","note":"The back-cover summary or blurb copy.","provision":"diy"},{"localId":"nf-set-a-tentative-placeholder-target-pub-d","name":"Set a tentative/placeholder target pub date","requirement":"complete_activity_outside","note":"Lightweight and early — feeds the schedule without a firm commitment."},{"localId":"nf-start-lightweight-list-building-platform","name":"Start lightweight list-building / platform-building","requirement":"complete_activity_outside","note":"Begin building an audience now — platform matters even more for nonfiction, since readers often buy on the author's authority.","provision":"diy"},{"localId":"nf-create-an-author-website-conditional","name":"Create an author website (conditional)","requirement":"complete_activity_outside","note":"Skip this one if you already have a site.","provision":"diy"}]},{"id":"editing","name":"Editing","mode":"Loop","summary":"Move from structural clarity to clean, confident prose.","milestones":[{"localId":"nf-copyedit-pass-ai-assisted-chapter-by-cha","name":"Copyedit pass, AI-assisted, chapter by chapter","requirement":"complete_activity_outside","note":"AI is a feedback and thinking partner here, never the author of the work — and never a substitute for a professional pass when budget allows.","provision":"diy"},{"localId":"nf-fact-check-citation-accuracy-pass","name":"Fact-check / citation-accuracy pass","requirement":"complete_activity_outside","note":"Verify every claim and citation before this goes any further — nonfiction's credibility rests on this."},{"localId":"nf-full-read-through-gate","name":"Full read-through gate","requirement":"approve_a_deliverable","note":"The gate that confirms Editing is actually done."},{"localId":"nf-lock-manuscript","name":"Lock manuscript","requirement":"complete_activity_outside","note":"Freeze the text here — only formatting changes from this point forward.","provision":"diy"}]},{"id":"production","name":"Production","mode":"Sprint","summary":"Turn the manuscript into a book people can hold and read.","milestones":[{"localId":"nf-select-cover-format-type","name":"Select cover format type","requirement":"complete_activity_outside","note":"Selecting to publish your book as a hardcover and/or as a paperback can impact the trim options allowed for publishing. Select the option that you desire to determine which trim size would work best for your book and if there is a minimum or maximum page count needed for the selected trim size."},{"localId":"nf-interior-formatting-including-index-gene","name":"Interior formatting (including index generation)","requirement":"attach_a_file","note":"Lay out the interior and generate the index from the plan made earlier in Writing & Development.","track":"text"},{"localId":"nf-add-page-numbers-headers-and-footers","name":"Add page numbers, headers, and footers","requirement":"attach_a_file","note":"A tricky, time-consuming part of preparing the interiors of your book is ensuring the page headers and footers are properly configured. When using a downloaded template, they are typically configured accordingly, so each time a new page is added in a section, the document corrects itself. Add page numbers to the bottom of your book pages. Make sure your front and back matter is all in place, headers show on the correct pages, and the footer is configured with the page number placement you want. Page numbers will be fully locked in later in this phase.","track":"text","provision":"diy"},{"localId":"nf-update-table-of-contents","name":"Update table of contents","requirement":"attach_a_file","note":"Inserting page numbers and configuring them accurately across front matter, interior text, and back matter can be a time-consuming process. Sections in the book template impact how the numbering appears. Once pages are numbered as best as they can be, update the table of contents. It is important to not stress too much right now about the numbering. A few milestones down, when the book is previewed in the publication’s site, that will be the time to determine page-placement changes.","track":"text","provision":"diy"},{"localId":"nf-cover-design","name":"Cover design","requirement":"request_a_service","note":"Runs in parallel with interior formatting. Ask Pen to weigh DIY cover tools against hiring a designer based on your budget.","track":"design"},{"localId":"nf-book-draft-creation-on-amazon-kdp-and-or","name":"Book draft creation on Amazon KDP and/or Ingramspark","requirement":"complete_activity_outside","note":"Create an account or login to your chosen publication sites (e.g., Amazon KDP or Ingramspark). Enter all the necessary details about your book and its content. [This milestone runs parallel to the following two regarding the ISBN decisions.]","track":"publishing","provision":"diy"},{"localId":"nf-isbn-decision-free-vs-purchased","name":"ISBN decision: free vs. purchased","requirement":"complete_activity_outside","note":"A real decision with real consequences — switching later means redoing every file the ISBN touches. Ask Pen to walk through the tradeoffs.","track":"publishing"},{"localId":"nf-isbn-purchase-quantity","name":"ISBN purchase & quantity","requirement":"complete_activity_outside","note":"Buy through Bowker (US) or your country's ISBN agency — one per print format; the KDP ebook needs none.","track":"publishing","provision":"diy"},{"localId":"nf-cover-and-manuscript-upload-approval","name":"Cover and manuscript upload approval","requirement":"complete_activity_outside","note":"Whether you are self-publishing directly on Amazon KDP or Ingramspark — you have to upload the manuscript and cover (likely multiple times) before it is approved without errors. Your book can remain in draft mode for as long as necessary until you get this part right. Once both are uploaded, the sites will trigger their automated format-check on your manuscript and cover files.","track":"publishing","provision":"diy"},{"localId":"nf-ingramspark-and-amazon-kdp-listing-forma","name":"IngramSpark and Amazon KDP listing + format final check","requirement":"complete_activity_outside","note":"Once your book details are added and your manuscript and cover are approved with no errors, you are ready to ‘submit your book for publication’. This can be done directly on IngramSpark using a future publication date, while in parallel with the KDP draft, which runs its own format check too.","track":"publishing","provision":"diy"},{"localId":"nf-ingramspark-preorder-scheduling","name":"IngramSpark preorder scheduling","requirement":"complete_activity_outside","note":"Scheduled on IngramSpark. Connecting it to the KDP draft has a real lead time.","track":"publishing","provision":"diy"},{"localId":"nf-build-the-ebook-file","name":"Build the ebook file","requirement":"attach_a_file","note":"Built directly in KDP's own ebook tool — no separate ISBN required for this format.","track":"text","provision":"diy"},{"localId":"nf-set-final-pricing","name":"Set final pricing","requirement":"complete_activity_outside","note":"Set directly on each platform — KDP, IngramSpark, and any others you're using.","track":"publishing","provision":"diy"},{"localId":"nf-order-physically-verify-proof-copies","name":"Order & physically verify proof copies","requirement":"complete_activity_outside","note":"Order a real, physical proof from both platforms and check it by hand — the human check that catches what automated format-checks can't.","track":"publishing","provision":"diy"}]},{"id":"pre_launch","name":"Pre-Launch","mode":"Sprint","summary":"Prepare the listing, early readers, and a realistic launch plan.","milestones":[{"localId":"nf-firm-up-the-pub-date","name":"Firm up the pub date","requirement":"complete_activity_outside","note":"The second, harder date commitment — flips the placeholder date to confirmed.","provision":"diy"},{"localId":"nf-build-activate-the-arc-team","name":"Build & activate the ARC team","requirement":"request_a_service","note":"Needs the longest lead time in this phase. Never run one before? Ask Pen — it'll walk you through what an ARC team is and how to recruit one.","provision":"hire"},{"localId":"nf-continue-list-building-platform-building","name":"Continue list-building / platform-building","requirement":"complete_activity_outside","note":"Keep growing your audience — for nonfiction, this is frequently the single biggest driver of sales.","provision":"diy"},{"localId":"nf-content-marketing-blogging-begins","name":"Content marketing / blogging begins","requirement":"complete_activity_outside","note":"Often the strongest marketing channel for nonfiction — start publishing in earnest once you have a concrete asset to build content around.","provision":"diy"},{"localId":"nf-ebook-preorder-goes-live","name":"Ebook preorder goes live","requirement":"complete_activity_outside","note":"Live on the platform you're using for preorders.","provision":"diy"},{"localId":"nf-secure-early-editorial-reviews","name":"Secure early/editorial reviews","requirement":"request_a_service","note":"Distinct from your ARC readers' own reviews — typically from editorial outlets or professional reviewers.","provision":"hire"},{"localId":"nf-final-sprint","name":"Final sprint","requirement":"complete_activity_outside","note":"The last 1–2 weeks — countdown emails, reminder posts, the final push.","provision":"diy"}]},{"id":"launch","name":"Launch","mode":"Launch window","summary":"Publish, verify every storefront, and invite the first readers.","milestones":[{"localId":"nf-click-publish","name":"Click publish","requirement":"complete_activity_outside","note":"The single action everything before it has been building toward.","provision":"diy"},{"localId":"nf-verify-live-and-correct-on-both-platform","name":"Verify live and correct on both platforms","requirement":"approve_a_deliverable","note":"Confirm before you announce — this instinct has run through every gate in this template."},{"localId":"nf-announce-social-media","name":"Announce: social media","requirement":"complete_activity_outside","note":"Share the launch across your social channels.","provision":"diy"},{"localId":"nf-announce-blog-post","name":"Announce: blog post","requirement":"complete_activity_outside","note":"Publish a launch-day post on your own site.","provision":"diy"},{"localId":"nf-announce-email-list","name":"Announce: email list","requirement":"complete_activity_outside","note":"Email your list that the book is live.","provision":"diy"},{"localId":"nf-update-author-website-preorder-live","name":"Update author website (preorder → live)","requirement":"complete_activity_outside","note":"A small, easy-to-forget step — flip your site's status the same day you publish.","provision":"diy"}]},{"id":"post_launch_growth","name":"Post-Launch & Growth","mode":"Loop","summary":"Learn from the launch and build steady readership.","milestones":[{"localId":"nf-marketing-push-begins-with-changed-messa","name":"Marketing push begins, with changed messaging","requirement":"complete_activity_outside","note":"Same channels as before, different message — shift from anticipation copy to reader-response energy.","provision":"diy"},{"localId":"nf-order-author-copies","name":"Order author copies","requirement":"complete_activity_outside","note":"Physical stock for signings, gifts, and direct sales.","provision":"diy"},{"localId":"nf-consider-speaking-workshop-opportunities","name":"Consider speaking/workshop opportunities","requirement":"complete_activity_outside","note":"A nonfiction-specific growth channel — speaking and workshops tied to the book's topic can outlast any single marketing push."}]}]$tpl$::jsonb, updated_at = now() WHERE id = 'e27ee5ef-23d5-4a1b-ab8b-07517bf2da36' AND owner_id IS NULL;
  GET DIAGNOSTICS _n = ROW_COUNT; RAISE NOTICE 'Nonfiction / How-To: % template row(s) updated', _n;
  UPDATE public.templates SET phases = $tpl$[{"id":"writing_development","name":"Writing & Development","mode":"Loop","summary":"Shape the manuscript, test the premise, and revise with intention.","milestones":[{"localId":"pb-capture-the-idea","name":"Capture the idea","requirement":"complete_activity_outside","note":"Raw notebook dump — the core story idea, no structure yet.","provision":"diy"},{"localId":"pb-draft-the-manuscript-short-form","name":"Draft the manuscript (short-form)","requirement":"attach_a_file","note":"Write the text directly — spreads and page count replace “chapters” here; there's no separate outline stage for something this short.","provision":"diy"},{"localId":"pb-layered-revision-passes","name":"Layered revision passes","requirement":"complete_activity_outside","note":"Extending and refining the manuscript over multiple rounds.","provision":"diy"},{"localId":"pb-early-spot-check-read-often-with-actual-","name":"Early spot-check read (often with actual child readers/listeners)","requirement":"request_a_service","note":"Test it on real kids early, not just adult readers — reactions read aloud differ a lot from reactions on the page.","provision":"hire"},{"localId":"pb-deep-revision-ai-assisted","name":"Deep revision (AI-assisted)","requirement":"complete_activity_outside","note":"AI is a feedback and thinking partner here, never the author of the work — and never a substitute for a professional pass when budget allows.","provision":"diy"},{"localId":"pb-structured-beta-reader-survey-round-pare","name":"Structured beta-reader survey round (parent/educator readers)","requirement":"request_a_service","note":"Get structured feedback from the adults who'll actually be reading it aloud, not just peer authors.","provision":"hire"},{"localId":"pb-weigh-incorporate-feedback","name":"Weigh & incorporate feedback","requirement":"complete_activity_outside","note":"The deliberate judgment call after the survey, distinct from collecting it.","provision":"diy"},{"localId":"pb-full-manuscript-read-through-readiness-g","name":"Full manuscript read-through (readiness gate)","requirement":"approve_a_deliverable","note":"The gate that decides Writing & Development is actually done."},{"localId":"pb-draft-back-cover-summary-blurb-copy","name":"Draft back-cover summary / blurb copy","requirement":"attach_a_file","note":"The back-cover summary or blurb copy.","provision":"diy"},{"localId":"pb-set-a-tentative-placeholder-target-pub-d","name":"Set a tentative/placeholder target pub date","requirement":"complete_activity_outside","note":"Lightweight and early — illustration adds real lead time here, so this matters even more than usual."},{"localId":"pb-start-lightweight-list-building","name":"Start lightweight list-building","requirement":"complete_activity_outside","note":"A sign-up page plus casual behind-the-scenes posts. Starts here, not in Pre-Launch.","provision":"diy"},{"localId":"pb-create-an-author-website-conditional","name":"Create an author website (conditional)","requirement":"complete_activity_outside","note":"Skip this one if you already have a site.","provision":"diy"}]},{"id":"editing","name":"Editing","mode":"Loop","summary":"Move from structural clarity to clean, confident prose.","milestones":[{"localId":"pb-copyedit-pass-ai-assisted","name":"Copyedit pass, AI-assisted","requirement":"complete_activity_outside","note":"AI is a feedback and thinking partner here, never the author of the work — and never a substitute for a professional pass when budget allows.","provision":"diy"},{"localId":"pb-full-read-through-gate","name":"Full read-through gate","requirement":"approve_a_deliverable","note":"The gate that confirms Editing is actually done."},{"localId":"pb-lock-manuscript","name":"Lock manuscript","requirement":"complete_activity_outside","note":"Freeze the text here.","provision":"diy"}]},{"id":"production","name":"Production","mode":"Sprint","summary":"Turn the manuscript into a book people can hold and read.","milestones":[{"localId":"pb-commission-illustrator","name":"Commission illustrator","requirement":"request_a_service","note":"Hire an illustrator now — this has the longest lead time of any single step in this template, so start it as early as the budget allows.","track":"design","provision":"hire"},{"localId":"pb-illustration-rounds-sketches-dummy-revis","name":"Illustration rounds: sketches/dummy → revisions → final art","requirement":"request_a_service","note":"Move through rough sketches, a dummy layout, revisions, and final artwork with your illustrator — expect several rounds, not one handoff.","track":"design","provision":"hire"},{"localId":"pb-select-cover-format-type","name":"Select cover format type","requirement":"complete_activity_outside","note":"Selecting to publish your book as a hardcover and/or as a paperback can impact the trim options allowed for publishing. Select the option that you desire to determine which trim size would work best for your book and if there is a minimum or maximum page count needed for the selected trim size."},{"localId":"pb-interior-formatting-spreads-not-chapters","name":"Interior formatting (spreads, not chapters)","requirement":"attach_a_file","note":"Lay out the book by spread once the final art is in hand — formatting can't really start before illustration is done.","track":"text"},{"localId":"pb-add-page-numbers-headers-and-footers","name":"Add page numbers, headers, and footers","requirement":"attach_a_file","note":"A tricky, time-consuming part of preparing the interiors of your book is ensuring the page headers and footers are properly configured. When using a downloaded template, they are typically configured accordingly, so each time a new page is added in a section, the document corrects itself. Add page numbers to the bottom of your book pages. Make sure your front and back matter is all in place, headers show on the correct pages, and the footer is configured with the page number placement you want. Page numbers will be fully locked in later in this phase. For a picture book, page numbers are usually minimal and unobtrusive so they don't compete with the art.","track":"text","provision":"diy"},{"localId":"pb-update-table-of-contents","name":"Update table of contents","requirement":"attach_a_file","note":"Most picture books skip a formal table of contents entirely. Check your chosen platform's template — if one is required or included by default, confirm it reflects the final page numbers; otherwise this step can be skipped.","track":"text","provision":"diy"},{"localId":"pb-cover-design-often-derived-from-interior","name":"Cover design (often derived from interior illustrations)","requirement":"request_a_service","note":"Build the cover from the same art style as the interior, usually with the same illustrator.","track":"design","provision":"hire"},{"localId":"pb-book-draft-creation-on-amazon-kdp-and-or","name":"Book draft creation on Amazon KDP and/or Ingramspark","requirement":"complete_activity_outside","note":"Create an account or login to your chosen publication sites (e.g., Amazon KDP or Ingramspark). Enter all the necessary details about your book and its content. [This milestone runs parallel to the following two regarding the ISBN decisions.]","track":"publishing","provision":"diy"},{"localId":"pb-isbn-decision-free-vs-purchased","name":"ISBN decision: free vs. purchased","requirement":"complete_activity_outside","note":"A real decision with real consequences — switching later means redoing every file the ISBN touches.","track":"publishing"},{"localId":"pb-isbn-purchase-quantity","name":"ISBN purchase & quantity","requirement":"complete_activity_outside","note":"Buy through Bowker (US) or your country's ISBN agency — one per print format; the KDP ebook needs none.","track":"publishing","provision":"diy"},{"localId":"pb-cover-and-manuscript-upload-approval","name":"Cover and manuscript upload approval","requirement":"complete_activity_outside","note":"Whether you are self-publishing directly on Amazon KDP or Ingramspark — you have to upload the manuscript and cover (likely multiple times) before it is approved without errors. Your book can remain in draft mode for as long as necessary until you get this part right. Once both are uploaded, the sites will trigger their automated format-check on your manuscript and cover files.","track":"publishing","provision":"diy"},{"localId":"pb-ingramspark-and-amazon-kdp-listing-forma","name":"IngramSpark and Amazon KDP listing + format final check","requirement":"complete_activity_outside","note":"Once your book details are added and your manuscript and cover are approved with no errors, you are ready to ‘submit your book for publication’. This can be done directly on IngramSpark using a future publication date, while in parallel with the KDP draft, which runs its own format check too.","track":"publishing","provision":"diy"},{"localId":"pb-ingramspark-preorder-scheduling","name":"IngramSpark preorder scheduling","requirement":"complete_activity_outside","note":"Scheduled on IngramSpark. Connecting it to the KDP draft has a real lead time.","track":"publishing","provision":"diy"},{"localId":"pb-build-the-ebook-file","name":"Build the ebook file","requirement":"attach_a_file","note":"Built directly in KDP's own ebook tool.","track":"text","provision":"diy"},{"localId":"pb-set-final-pricing","name":"Set final pricing","requirement":"complete_activity_outside","note":"Set directly on each platform.","track":"publishing","provision":"diy"},{"localId":"pb-order-physically-verify-proof-copies","name":"Order & physically verify proof copies","requirement":"complete_activity_outside","note":"Color accuracy matters more here than in any other template — check it in hand before publishing, not just on screen.","track":"publishing","provision":"diy"}]},{"id":"pre_launch","name":"Pre-Launch","mode":"Sprint","summary":"Prepare the listing, early readers, and a realistic launch plan.","milestones":[{"localId":"pb-firm-up-the-pub-date","name":"Firm up the pub date","requirement":"complete_activity_outside","note":"The second, harder date commitment — flips the placeholder date to confirmed.","provision":"diy"},{"localId":"pb-build-activate-the-arc-team-teachers-lib","name":"Build & activate the ARC team (teachers/librarians)","requirement":"request_a_service","note":"Recruit readers who reach classrooms and libraries specifically — a different pool than a typical adult-fiction ARC team.","provision":"hire"},{"localId":"pb-continue-list-building","name":"Continue list-building","requirement":"complete_activity_outside","note":"A continuation of the list you started earlier.","provision":"diy"},{"localId":"pb-content-marketing-blogging-begins","name":"Content marketing / blogging begins","requirement":"complete_activity_outside","note":"Start posting once the cover or interior art is ready to show — art carries picture-book marketing more than text excerpts do.","provision":"diy"},{"localId":"pb-ebook-preorder-goes-live","name":"Ebook preorder goes live","requirement":"complete_activity_outside","note":"Live on the platform you're using for preorders.","provision":"diy"},{"localId":"pb-secure-early-editorial-reviews","name":"Secure early/editorial reviews","requirement":"request_a_service","note":"Distinct from your ARC readers' own reviews.","provision":"hire"},{"localId":"pb-final-sprint","name":"Final sprint","requirement":"complete_activity_outside","note":"The last 1–2 weeks — countdown emails, reminder posts.","provision":"diy"}]},{"id":"launch","name":"Launch","mode":"Launch window","summary":"Publish, verify every storefront, and invite the first readers.","milestones":[{"localId":"pb-click-publish","name":"Click publish","requirement":"complete_activity_outside","note":"The single action everything before it has been building toward.","provision":"diy"},{"localId":"pb-verify-live-and-correct-on-both-platform","name":"Verify live and correct on both platforms","requirement":"approve_a_deliverable","note":"Confirm before you announce."},{"localId":"pb-announce-social-media","name":"Announce: social media","requirement":"complete_activity_outside","note":"Share the launch across your social channels.","provision":"diy"},{"localId":"pb-announce-blog-post","name":"Announce: blog post","requirement":"complete_activity_outside","note":"Publish a launch-day post on your own site.","provision":"diy"},{"localId":"pb-announce-email-list","name":"Announce: email list","requirement":"complete_activity_outside","note":"Email your list that the book is live.","provision":"diy"},{"localId":"pb-update-author-website-preorder-live","name":"Update author website (preorder → live)","requirement":"complete_activity_outside","note":"A small, easy-to-forget step.","provision":"diy"}]},{"id":"post_launch_growth","name":"Post-Launch & Growth","mode":"Loop","summary":"Learn from the launch and build steady readership.","milestones":[{"localId":"pb-marketing-push-begins-with-changed-messa","name":"Marketing push begins, with changed messaging","requirement":"complete_activity_outside","note":"Same channels as before, different message — shift from anticipation copy to reader-response energy.","provision":"diy"},{"localId":"pb-order-author-copies","name":"Order author copies","requirement":"complete_activity_outside","note":"Physical stock for signings, gifts, and direct sales.","provision":"diy"},{"localId":"pb-consider-school-library-outreach","name":"Consider school/library outreach","requirement":"complete_activity_outside","note":"A picture-book-specific growth channel — school visits and library programs can matter more than typical adult-book marketing."}]}]$tpl$::jsonb, updated_at = now() WHERE id = '93539610-b2a6-4dba-a131-7bcc06759f0a' AND owner_id IS NULL;
  GET DIAGNOSTICS _n = ROW_COUNT; RAISE NOTICE 'Picture Book: % template row(s) updated', _n;
END $$;
